      "version": "60824.1",
      "config": {
        "retention_days": 10
      }
    },
    "local/edfringe",
    "local/edfringe-data",
    "local/edfringe-requirements",
    {
      "id": "executable-requirements",
      "version": "60822.1",
      "config": {
        "spec": "product/requirements.md"
      },
      "answers": {
        "ui_testing": "Headless Chromium via Playwright (pre-installed in the environment): render the real single-page app \u2014 Leaflet map included, with map tiles and other network faked deterministically \u2014 and assert pixel-exact visual goldens the owner reviews by sight; short per-leaf tests drive to a state and capture. Pure planner rules (plan/lib) stay node --test logic leaves. No visual harness exists yet \u2014 this is the target mechanism.",
        "requirements_source": "Authored fresh at product/requirements.md (config.spec), distilled from the existing product brief docs/product-spec.md. No prior formal requirements doc or issue-tracker backlog to extract."
      }
    },
    {
      "id": "spec-driven-product",
      "version": "60822.1"
    },
    {
      "id": "static-website",
      "version": "60823.1",
